mapper.select:
SELECT TO_CHAR(t1.YMD, 'YYYY-MM-DD') AS ymd , hj.JM_CD AS jm_cd , hj.HJ_NM AS hj_nm , TO_CHAR(hj.SANGHW_YMD, 'YYYY-MM-DD') AS sanghw_ymd , TO_CHAR(hj.AF_IJA_YMD, 'YYYY-MM-DD') AS af_ija_ymd , hj.PYOM_IYUL AS pyom_iyul , ROUND(hj.PYOM_IYUL * 100, 4) AS pyom_per , t1.FUND_CD AS fund_cd , ia.FUND_NM AS fund_nm , (NVL(t1.bfil_aekm, 0) + NVL(t1.meib_aekm, 0) - NVL(t1.medo_aekm, 0)) / 10000 AS com_aekm , (NVL(t1.bfil_chui_aek, 0) + NVL(t1.meib_aek, 0) + NVL(t1.anbun_aek, 0) - NVL(t1.medo_aek, 0)) AS com_chui_aek , CASE WHEN hj.CASH_CD = '90' THEN t1.MEIB_AEK ELSE (NVL(t1.bfil_chui_aek, 0) + NVL(t1.meib_aek, 0) + NVL(t1.anbun_aek, 0) - NVL(t1.medo_aek, 0)) END AS chui_aek , t1.MISU_IJA AS misu_ija , t1.DAY_IJA AS day_ija , NVL(t1.bfil_sunsu_ija, 0) + NVL(t1.up_sunsu_ija, 0) - NVL(t1.dw_sunsu_ija, 0) AS sunsu_ija , NVL(t1.dw_sunsu_ija, 0) AS dw_sunsu_ija , t1.PYUNGA_AEK AS pyunga_aek , t1.SIGA_AEK AS siga_aek , t1.MEIB_AEK AS meib_aek , hj.CASH_CD AS cash_cd , ia.mg_cd AS mg_cd , ia.TYPE_GB AS type_gb , t1.YUHYO_RT AS yuhyo_rt , hj.NOW_IJA_HOICHA AS now_ija_hoicha , 2960685 AS fund_color FROM SHM0HM t1 JOIN SHM0HJ hj ON hj.CORP_GR = t1.CORP_GR AND hj.JM_CD = t1.JM_CD JOIN SZM0IA ia ON ia.CORP_GR = t1.CORP_GR AND ia.FUND_CD = t1.FUND_CD WHERE t1.CORP_GR = #{corpGr} AND t1.YMD BETWEEN TO_DATE(REPLACE(#{fymd}, '-', ''), 'YYYYMMDD') AND TO_DATE(REPLACE(#{tymd}, '-', ''), 'YYYYMMDD')
AND hj.CASH_CD LIKE #{cashCd}
AND hj.JM_CD = #{hjCd}
AND ia.FUND_CD = #{fundCd}
ORDER BY t1.YMD, hj.JM_CD, t1.FUND_CD
ORDER BY t1.YMD, t1.FUND_CD, hj.JM_CD
ORDER BY t1.YMD, hj.JM_CD, t1.FUND_CD

{ CALL KFP.SR_JA030J(
    #{corpGr, mode=IN, jdbcType=VARCHAR},
    #{ymd, mode=IN, jdbcType=VARCHAR},
    #{fundCd, mode=IN, jdbcType=VARCHAR},
    #{jmCd, mode=IN, jdbcType=VARCHAR},
    #{rSet, mode=OUT, jdbcType=CURSOR, javaType=java.sql.ResultSet, resultMap=ja030jDetailResultMap}
) }
